/* AbiLearn — Social Science Extra MCQs — Ch 11, 12, 13 (150 harder Questions) */

const SOCIAL_CH11_EXTRA = [
  { q: 'The Diamond Sutra (868 CE) is significant because it is:', opts: ['The first book printed on a Gutenberg press', 'The oldest dated printed book in the world', 'The first European printed text', 'The first book printed in India'], ans: 1, exp: 'The Diamond Sutra (868 CE), a Buddhist text, is the world\'s oldest dated printed book, produced using woodblock printing in Tang Dynasty China.' },
  { q: 'Which commodity caused Rome to lose large amounts of gold and silver to Asia in ancient trade?', opts: ['Silk and spices', 'Cotton and indigo', 'Copper and tin', 'Ivory and gems'], ans: 0, exp: 'Rome imported silk, spices, and other luxury goods from Asia and paid in gold and silver, leading to a drain of precious metals from the Roman Empire.' },
  { q: 'The term "Girmitiya" for indentured labourers comes from:', opts: ['A Portuguese word meaning servant', 'A Hindi corruption of the word "agreement"', 'The name of a ship that carried workers', 'A British administrative term'], ans: 1, exp: 'Girmitiya is a Hindi corruption of "agreement" — the 5-year labour contract that indentured workers signed to work in overseas British colonies.' },
  { q: 'Indentured workers from India were sent to all EXCEPT:', opts: ['Fiji', 'Trinidad', 'Mauritius', 'Australia'], ans: 3, exp: 'Indian indentured workers were sent to Fiji, Trinidad, Mauritius, British Guiana, Natal (South Africa), and other colonies — not Australia (which had White Australia Policy).' },
  { q: 'The Rinderpest cattle disease devastated Africa in the 1890s by:', opts: ['Killing human populations in cattle-rearing communities', 'Killing up to 90% of cattle, destroying African livelihoods and forcing people into wage labour', 'Contaminating Africa\'s grain supply', 'Eliminating Africa\'s wild game'], ans: 1, exp: 'Rinderpest (cattle plague) spread from British-imported Asian cattle in 1890s Africa, killed 90% of cattle in some areas, destroying food sources and forcing Africans into colonial labour markets.' },
  { q: 'Thomas Malthus\'s theory of population predicts that:', opts: ['Population growth will always exceed food supply, leading to periodic catastrophes', 'Food supply always outpaces population', 'Industrial growth automatically controls population', 'Migration solves population pressure'], ans: 0, exp: 'Malthus (1798, "Essay on Population") argued population grows geometrically (1,2,4,8...) while food production grows arithmetically (1,2,3,4...) — leading to famine, disease, or war as natural checks.' },
  { q: 'The Corn Laws in Britain were repealed in 1846 due to pressure from:', opts: ['Landlords wanting to export grain', 'Industrialists and workers who wanted cheap food and free trade', 'Colonial governments', 'The Irish famine directly'], ans: 1, exp: 'The Anti-Corn Law League, led by Richard Cobden and John Bright, campaigned successfully for repeal (1846). Industrialists wanted cheap food for workers; free traders wanted open markets.' },
  { q: 'After the repeal of Corn Laws in 1846, Britain began to import cheap grain from:', opts: ['Canada and Australia', 'Eastern Europe, Russia, and the Americas', 'India and China', 'Africa and West Indies'], ans: 1, exp: 'After 1846, cheap food flooded into Britain from Eastern Europe (Ukraine, Russia), the Americas (USA, Argentina), and later Australia — transforming global grain trade.' },
  { q: 'The US stock market crashed in:', opts: ['August 1929', 'October 1929', 'January 1930', 'December 1931'], ans: 1, exp: 'The Great Depression began with the US stock market crash on "Black Thursday" and "Black Tuesday" in October 1929 (24th and 29th October), triggering a global economic crisis.' },
  { q: 'The Smoot-Hawley Tariff Act (1930) raised US import tariffs to approximately:', opts: ['10%', '25%', '50%', '75%'], ans: 2, exp: 'The Smoot-Hawley Tariff Act raised US import tariffs to about 50% — the highest in US history — triggering retaliatory tariffs globally and deepening the Depression.' },
  { q: 'Between 1929 and 1932, US national income fell by approximately:', opts: ['10%', '25%', '50%', '75%'], ans: 2, exp: 'US national income fell by about 50% between 1929 and 1932. Unemployment rose to 17 million (about 25% of the workforce), the worst economic crisis in modern history.' },
  { q: 'John Maynard Keynes argued during the Depression that governments should:', opts: ['Reduce spending and balance budgets', 'Increase spending (deficit spending) to stimulate demand', 'Raise tariffs to protect industries', 'Reduce money supply to control inflation'], ans: 1, exp: 'Keynes argued that government deficit spending was needed to revive demand during recessions. This Keynesian economics influenced Roosevelt\'s New Deal and post-WW2 economic policy.' },
  { q: 'The Bretton Woods Conference (1944) was held in:', opts: ['London, UK', 'New York, USA', 'New Hampshire, USA', 'Geneva, Switzerland'], ans: 2, exp: 'The Bretton Woods Conference was held at Bretton Woods, New Hampshire, USA in July 1944, creating the IMF and World Bank (IBRD) to manage post-war international finance.' },
  { q: 'The Bretton Woods system established what type of exchange rate?', opts: ['Floating exchange rates', 'Fixed exchange rates with dollar pegged to gold at $35/troy oz', 'Exchange rates determined by market forces', 'Bilateral fixed rates between countries'], ans: 1, exp: 'Bretton Woods established fixed exchange rates — all currencies were pegged to the US dollar, which was in turn pegged to gold at $35 per troy ounce (gold-dollar standard).' },
  { q: 'GATT (1947) was primarily focused on:', opts: ['Creating the IMF', 'Building the World Bank', 'Reducing tariffs and trade barriers through multilateral negotiations', 'Managing exchange rates'], ans: 2, exp: 'GATT (General Agreement on Tariffs and Trade, 1947) focused on reducing tariff barriers through negotiating "rounds." It was replaced by the WTO in 1995.' },
  { q: 'The Marshall Plan (1948) was a US programme to:', opts: ['Rebuild Japan after WW2', 'Reconstruct war-devastated Western Europe economically', 'Fund the Korean War', 'Establish NATO'], ans: 1, exp: 'Marshall Plan provided $13 billion in US economic aid (1948–52) to rebuild Western European economies devastated by WW2, also containing Soviet influence.' },
  { q: 'The "Golden Age" of the post-war world economy (1947–1975) was characterised by:', opts: ['Annual growth of 2%, rising unemployment', 'Annual growth of ~5%, world trade grew 8%/year, unemployment under 5%', 'Deflation and falling wages', 'Slowdown due to oil prices'], ans: 1, exp: 'The post-war Golden Age saw unprecedented economic growth: ~5% annual growth, world trade expanding 8% per year, full employment, and rising living standards in the West.' },
  { q: 'UNCTAD (1964) was formed by developing countries to demand:', opts: ['Military alliances against colonial powers', 'A New International Economic Order with fairer trade terms for developing nations', 'Entry into the UN Security Council', 'Access to nuclear technology'], ans: 1, exp: 'UNCTAD (UN Conference on Trade and Development) was formed by the G-77 developing nations to demand fairer terms of trade, technology transfer, and development aid from rich nations.' },
  { q: 'Stagflation (1970s) refers to a situation of:', opts: ['High growth and high inflation', 'Low growth with high inflation simultaneously', 'Low growth with deflation', 'High employment with rising wages'], ans: 1, exp: 'Stagflation = stagnation + inflation — low economic growth with high unemployment AND rising prices simultaneously. The 1973 OPEC oil shock caused stagflation in Western economies.' },
  { q: 'The Washington Consensus refers to:', opts: ['An agreement between USA and UK on nuclear weapons', 'A policy framework promoting deregulation, privatisation, and fiscal austerity for developing nations', 'A climate change accord', 'US–China trade agreement'], ans: 1, exp: 'Washington Consensus (1980s–90s) was a set of economic policies (free markets, deregulation, privatisation, fiscal discipline) promoted by IMF and World Bank for developing countries.' },
  { q: 'V.S. Naipaul, Nobel Prize-winning writer, had ancestral connection to globalisation through:', opts: ['Being a British colonial officer in India', 'His family coming to Trinidad as indentured workers from India', 'His grandfather being a Silk Road merchant', 'His father being a World Bank economist'], ans: 1, exp: 'V.S. Naipaul\'s family were Indian indentured labourers (Girmitiya) who went to Trinidad. His ancestral story reflects the indentured labour migration that was part of 19th-century globalisation.' },
  { q: 'The WTO was established in:', opts: ['1944', '1947', '1991', '1995'], ans: 3, exp: 'WTO (World Trade Organisation) was established on 1 January 1995, replacing GATT (1947). It has 164 members and enforces multilateral trade rules with a dispute settlement system.' },
  { q: 'The 2008 Global Financial Crisis originated from:', opts: ['European sovereign debt', 'US subprime mortgage market collapse spreading to global financial systems', 'Chinese currency manipulation', 'OPEC oil price spike'], ans: 1, exp: 'The 2008 crisis originated from US subprime mortgage defaults, which spread through complex financial derivatives (CDOs, CDSs) to global banks, triggering the worst recession since 1929.' },
  { q: 'The indentured labour system was called "a new system of slavery" because:', opts: ['Workers were legally owned by employers', 'Workers had no freedom to leave before 5 years, faced harsh conditions, and had no real choice', 'Workers were brought in ships like slaves', 'Workers received no pay'], ans: 1, exp: 'Though technically "free labour" under contract, indentured workers faced debt traps, punitive laws for breach of contract, harsh living conditions, and no real freedom — akin to slavery.' },
  { q: 'Which commodity most enabled the rise of global trade in the 19th century by dramatically reducing shipping costs and time?', opts: ['Steam-powered ships and telegraph', 'Canal building', 'Railroad networks', 'Refrigerator ships (reefer ships)'], ans: 0, exp: 'Steam-powered ships (reduced ocean crossing time) and the electric telegraph (instant communication) transformed 19th-century global trade, dramatically reducing transport costs and information delays.' },
  { q: 'Food safety innovations in the 19th century that enabled long-distance trade included:', opts: ['Freeze drying', 'Pasteurisation and canning', 'Refrigerated ships (reefer ships) carrying meat from Americas/Australia', 'Vacuum packaging'], ans: 2, exp: 'Refrigerated ships (reefer ships) from the 1870s allowed fresh meat, dairy, and fruit to be shipped from Argentina, USA, and Australia to Britain — transforming food trade.' },
  { q: 'By the 1890s, colonialism controlled approximately what percentage of the Earth\'s surface?', opts: ['50%', '65%', '75%', '85%'], ans: 3, exp: 'By the 1890s, European colonialism controlled about 85% of the Earth\'s land surface, linking distant economies into a global network of trade, migration, and capital flows.' },
  { q: 'The Silk Routes are important in global history because they:', opts: ['Were single roads linking China to Rome', 'Were a network of overland and sea routes connecting Asia, Africa, and Europe for trade', 'Were used only by Chinese traders', 'Were established in modern times (19th century)'], ans: 1, exp: 'The Silk Routes were a network of ancient trade paths — not a single road — connecting China, Central Asia, India, Middle East, Africa, and Europe, enabling exchange of goods, ideas, and diseases.' },
  { q: 'The role of cowrie shells in early global trade was that of:', opts: ['A luxury decorative item', 'A form of currency used in South Asia and Africa', 'A spice used in cooking', 'A religious symbol'], ans: 1, exp: 'Cowrie shells from the Maldives were used as currency in Africa and South Asia, demonstrating how global trade networks existed long before modern currencies.' },
  { q: 'MNCs shift production to low-wage countries primarily to:', opts: ['Follow WTO regulations', 'Reduce labour costs and increase profit margins', 'Avoid paying taxes in home countries only', 'Access better technology'], ans: 1, exp: 'MNCs locate production in developing countries (China, India, Vietnam, Bangladesh) primarily to reduce labour costs, also benefiting from lower environmental regulations, cheaper land, and proximity to markets.' },
  { q: 'The "Great Depression" got its name because:', opts: ['It caused massive depression/sadness among people', 'It was the most severe and prolonged economic downturn in modern history', 'Governments deliberately depressed prices', 'It started in a region called "Great" depression'], ans: 1, exp: 'The Great Depression (1929–1939) was the most severe and prolonged economic depression in modern history — "great" because of its scale, depth, and global reach.' },
  { q: 'Roosevelt\'s New Deal (1933) included all EXCEPT:', opts: ['Banking reform (Emergency Banking Act)', 'Agricultural support (AAA)', 'Raising tariffs (Smoot-Hawley)', 'Public works (PWA, CCC)'], ans: 2, exp: 'Smoot-Hawley tariffs were passed in 1930 under Hoover, not Roosevelt. Roosevelt\'s New Deal focused on banking reform, agricultural stabilisation, and public works programmes.' },
  { q: 'The IMF (International Monetary Fund) was created to:', opts: ['Give loans to developing countries for projects', 'Maintain exchange rate stability and provide short-term lending to countries with balance-of-payments problems', 'Regulate international trade', 'Manage foreign aid from rich to poor countries'], ans: 1, exp: 'IMF was created at Bretton Woods 1944 to maintain international monetary stability — providing short-term loans to countries with balance-of-payments crises and managing exchange rates.' },
  { q: 'The World Bank (IBRD) was created to:', opts: ['Manage currency exchange rates', 'Provide short-term crisis loans', 'Finance post-war reconstruction and development projects', 'Regulate global trade'], ans: 2, exp: 'The World Bank (International Bank for Reconstruction and Development) was created at Bretton Woods 1944 to provide long-term loans for post-war reconstruction of Europe and later for development projects in poorer countries.' },
  { q: 'Which president\'s "New Deal" most directly applied Keynesian principles to fight the Depression?', opts: ['Herbert Hoover', 'Franklin D. Roosevelt', 'Harry Truman', 'Woodrow Wilson'], ans: 1, exp: 'Franklin Roosevelt\'s New Deal (1933–39) used government spending (public works, social security, farm support) to stimulate demand — applying Keynesian economics before Keynes fully articulated the theory.' },
  { q: 'Indentured workers who completed their 5-year contracts had the option to:', opts: ['Automatically become British citizens', 'Return to India (at own cost) or take land grant and remain', 'Bring their families at government expense', 'Get permanent employment with the colonial government'], ans: 1, exp: 'After completing the 5-year contract, indentured workers could return to India at their own expense or accept a small plot of land and remain in the colony.' },
  { q: 'The phrase "The sun never sets on the British Empire" was most accurate during which period?', opts: ['1600–1700', '1750–1800', '1850–1920', '1920–1950'], ans: 2, exp: 'The phrase was most accurate between 1850–1920 when Britain controlled India, Australia, Canada, South Africa, West Africa, Egypt, and many other territories across all time zones.' },
  { q: 'WTO\'s dispute settlement mechanism allows member countries to:', opts: ['Wage economic war against trade partners', 'File complaints about trade rule violations and seek binding rulings', 'Impose any tariffs without justification', 'Subsidise industries freely'], ans: 1, exp: 'WTO\'s Dispute Settlement Body allows member nations to file complaints about trade violations. Panels hear cases and issue binding rulings — a key difference from GATT\'s weaker system.' },
  { q: 'How did colonial rule change Africa\'s economic structure through Rinderpest and other policies?', opts: ['It improved African agriculture', 'It forced subsistence farmers into wage labour in mines and plantations', 'It gave Africans land grants', 'It ended slave trade completely'], ans: 1, exp: 'Rinderpest (killing cattle), land seizures, and "hut taxes" (payable only in cash, not barter) forced African subsistence farmers into wage labour in British mines and farms.' },
  { q: 'The "open door" trade policy promoted by USA in the late 19th century referred to:', opts: ['Free immigration to the USA', 'Equal access to China\'s markets for all foreign powers', 'Open access to US natural resources', 'Free trade within the Americas'], ans: 1, exp: 'The Open Door Policy (1899, Secretary John Hay) demanded that all foreign powers have equal access to China\'s markets, preventing any one power from monopolising Chinese trade.' },
  { q: 'What was the significance of the introduction of new food crops from Americas to Europe after 1492?', opts: ['It had no significant effect on European population', 'Potatoes, maize, and tomatoes transformed European diets and helped population growth', 'Europeans rejected American food crops', 'It caused widespread famine in Europe'], ans: 1, exp: 'After 1492, American crops (potatoes, maize, tomatoes, sweet potatoes, cocoa) transformed world food production. Potatoes especially fuelled European population growth.' },
  { q: 'The term "triangular trade" refers to trade between:', opts: ['Asia, Europe, and America', 'England, France, and Germany', 'Africa, Americas, and Europe (guns→Africa, slaves→Americas, sugar/cotton→Europe)', 'India, China, and Arabia'], ans: 2, exp: 'Triangular slave trade: Europeans sent manufactured goods (guns, cloth) to Africa, African slaves to Americas, and American products (sugar, tobacco, cotton) back to Europe.' },
  { q: 'Which economist wrote "Imagined Communities" linking print capitalism to nationalism?', opts: ['Karl Marx', 'Benedict Anderson', 'Max Weber', 'Ernest Renan'], ans: 1, exp: 'Benedict Anderson\'s "Imagined Communities" (1983) argued that print capitalism created shared languages and national consciousness, enabling people to imagine themselves as part of a "nation."' },
  { q: 'The "golden straitjacket" (Thomas Friedman\'s term) of globalisation means:', opts: ['Rich countries benefit most from globalisation', 'Countries must accept free-market economic policies to participate in global economy', 'Gold standard controls globalisation', 'Trade agreements restrict developing nations'], ans: 1, exp: '"Golden straitjacket" = countries that accept globalisation get economic growth (gold) but must constrain themselves to free-market policies (straitjacket) — limited policy choices despite growth.' },
  { q: 'The Bretton Woods Conference led to the "dollar becoming the world\'s reserve currency." This means:', opts: ['Dollar replaced all other currencies', 'Countries held dollars as their main foreign exchange reserve instead of gold', 'USA owned the world\'s gold', 'Other countries could print dollars'], ans: 1, exp: 'After Bretton Woods, countries held US dollars as foreign exchange reserves (instead of gold) because dollars were convertible to gold at $35/oz. This made the US dollar the de facto world reserve currency.' },
  { q: 'The Great Depression spread from the USA to Europe primarily through:', opts: ['Military conflicts', 'US banks calling back loans from European countries and collapsing world trade', 'Migration of unemployed Americans', 'Spread of disease'], ans: 1, exp: 'US banks, themselves in crisis, recalled loans from European countries (especially Germany under Dawes Plan). This collapsed European banks and trade, spreading the Depression globally.' },
  { q: 'Technological innovation that most contributed to 19th century economic globalisation was:', opts: ['Printing press', 'Steam engine applied to ships and railways', 'Nuclear energy', 'Chemical fertilisers'], ans: 1, exp: 'Steam engine applied to ships (steamships crossing oceans in weeks vs months) and railways (connecting hinterlands to ports) was the most transformative technology for 19th-century globalisation.' },
  { q: 'The post-WW2 economic order was designed to avoid repeating the mistakes of:', opts: ['The First World War', 'The 1929 Great Depression and the protectionism/nationalism that followed', 'Colonial exploitation', 'The Russian Revolution'], ans: 1, exp: 'The architects of Bretton Woods (Keynes, White) designed the post-WW2 economic order to prevent a repeat of the 1929 Depression, the beggar-thy-neighbour tariff wars, and the political extremism they spawned.' },
  { q: 'Columbus\'s voyage to the Americas was funded by:', opts: ['Portuguese Crown', 'Spanish Crown (Ferdinand and Isabella)', 'British East India Company', 'Italian city-states'], ans: 1, exp: 'Columbus\'s 1492 voyage was funded by the Spanish Crown — King Ferdinand II and Queen Isabella I of Castile — after Portugal had already rejected his proposal.' },
  { q: 'After Columbus\'s 1492 voyage, the native American population declined dramatically due to:', opts: ['European military conquest alone', 'European diseases (smallpox, measles) killing 90%+ of native population with no immunity', 'Enslavement reducing birth rates', 'Climate change caused by European settlement'], ans: 1, exp: 'European diseases (smallpox, measles, typhus) to which native Americans had no immunity killed an estimated 50–90% of the indigenous population — more destructive than military conquest.' }
];

const SOCIAL_CH12_EXTRA = [
  { q: 'Proto-industrialisation was characterised by:', opts: ['Large factories with steam power', 'Rural cottage production organised by merchants who supplied raw materials', 'Government-run workshops', 'Colonial plantation labour'], ans: 1, exp: 'Proto-industrialisation (before factories) involved merchants supplying raw materials to rural peasant families who manufactured goods at home, creating a market-oriented production system.' },
  { q: 'The Spinning Jenny was invented in:', opts: ['1733', '1764', '1769', '1785'], ans: 1, exp: 'James Hargreaves invented the Spinning Jenny in 1764. It allowed one spinner to spin multiple threads simultaneously, threatening hand spinners who attacked Hargreaves\'s home.' },
  { q: 'Who invented the Steam Engine (1769) that transformed British industry?', opts: ['Thomas Newcomen', 'James Watt', 'Richard Arkwright', 'George Stephenson'], ans: 1, exp: 'James Watt improved Thomas Newcomen\'s earlier steam engine in 1769. Watt\'s engine was far more efficient and could be used to power machinery, not just pump water from mines.' },
  { q: 'Richard Arkwright is associated with:', opts: ['Spinning Jenny', 'Steam engine', 'Water frame and factory system', 'Power loom'], ans: 2, exp: 'Richard Arkwright invented the water frame (1769) and developed the factory system, building Cromford Mill. He established the discipline and organisation of industrial factory production.' },
  { q: 'Samuel Crompton\'s invention (the Spinning Mule, 1779) combined features of:', opts: ['Steam engine and water frame', 'Spinning Jenny and water frame', 'Power loom and cotton gin', 'Steam engine and Spinning Jenny'], ans: 1, exp: 'Crompton\'s Spinning Mule combined the Spinning Jenny (multiple spindles) and Arkwright\'s Water Frame (better quality) to spin fine, strong thread — enabling fine muslin production mechanically.' },
  { q: 'Edmund Cartwright\'s Power Loom (1785) was significant because:', opts: ['It could spin cotton', 'It mechanised weaving, the last major hand process in textiles', 'It processed raw cotton', 'It made steam engines more efficient'], ans: 1, exp: 'Cartwright\'s Power Loom (1785/1787) mechanised weaving — the stage that had remained manually intensive even after spinning was mechanised, completing the mechanisation of textile production.' },
  { q: 'The "Fly Shuttle" was invented in 1733 by:', opts: ['James Hargreaves', 'Edmund Cartwright', 'John Kay', 'Richard Arkwright'], ans: 2, exp: 'John Kay invented the Fly Shuttle in 1733. It allowed the shuttle carrying the weft thread to fly across the loom mechanically, doubling weaving speed. Indian handloom weavers adopted it by early 20th century.' },
  { q: 'Why did hand technology remain preferred in some textile sectors even after mechanisation?', opts: ['Machines were too expensive for all', 'Superfine cloth, delicate embroidery, and brocade required human dexterity machines could not replicate', 'Government banned machines', 'Machine cloth was illegal'], ans: 1, exp: 'Fine Dhaka muslin, intricate brocade (Varanasi), and delicate embroidery required hand skills that machines of the era could not replicate. Even in Britain, superfine weaving remained manual.' },
  { q: 'Dhaka muslin became famous for being:', opts: ['The strongest cotton cloth', 'So fine it was called "woven air" or "morning dew"', 'The most colourful printed cloth', 'The first machine-made cloth in India'], ans: 1, exp: 'Dhaka muslin was famously so fine it was called "woven air," "running water," or "morning dew" — the most delicate cotton fabric ever produced, woven by skilled artisans from the finest thread.' },
  { q: 'The "Staple" in medieval English trade was a town where:', opts: ['Crops were stored', 'Wool merchants gathered for processing and trade under royal licence', 'Ships were built', 'Workers were recruited'], ans: 1, exp: 'A "Staple" was a town (like Calais) designated by the English Crown where wool had to pass for processing, taxation, and sale — giving merchants there monopoly rights.' },
  { q: 'Jobbers in colonial Indian factories were:', opts: ['Factory supervisors appointed by British managers', 'Labour recruiters who brought workers from villages and often controlled them', 'Government labour inspectors', 'Skilled machine operators'], ans: 1, exp: 'Jobbers were labour recruiters who came from the same village/region as workers, guaranteed their employment and conduct, advanced money for migration, and often exploited workers through debt and commission.' },
  { q: 'Why did Indian industrialists initially focus on cotton textile mills in Bombay?', opts: ['British encouraged it', 'Cotton Deccan hinterland, cheap labour, Bombay port, and nationalist sentiment against British cloth imports', 'Government gave subsidies', 'Only cotton machines were available'], ans: 1, exp: 'Bombay had advantages: raw cotton from Deccan (Maharashtra, Gujarat), sea port for export, humid climate (good for spinning), labour from Deccan villages, and swadeshi sentiment against Manchester imports.' },
  { q: 'The first cotton textile mill in Bombay was established in:', opts: ['1818', '1854', '1876', '1907'], ans: 1, exp: 'The first cotton textile mill in Bombay was established in 1854 by Cowasjee Nanabhoy Davar — Bombay Spinning and Weaving Company. It began the modern textile industry in India.' },
  { q: 'Dwarkanath Tagore was an early Indian industrialist involved in:', opts: ['Cotton mills in Bombay', 'Jute mills, coal mines, and shipping in Bengal', 'Iron and steel in Jamshedpur', 'Tea plantations in Assam'], ans: 1, exp: 'Dwarkanath Tagore (1794–1846) was Bengal\'s first industrial entrepreneur — involved in coal mines (Raniganj), jute, indigo, silk, banking, and the Union Steam Service shipping company.' },
  { q: 'Dinshaw Petit was a pioneer in:', opts: ['Jute industry in Calcutta', 'Cotton textile mills in Bombay (Parsi entrepreneur)', 'Iron and steel in Jamshedpur', 'Coal mining in Jharkhand'], ans: 1, exp: 'Dinshaw Petit was a Parsi pioneer of Bombay\'s cotton textile industry in the 19th century. Parsi entrepreneurs played a key role alongside Marwaris in founding Bombay\'s mills.' },
  { q: 'Seth Hukumchand Marwari is remembered for:', opts: ['Setting up the first cotton mill in Ahmedabad', 'Setting up the first Indian jute mill in Calcutta in 1917', 'Starting TISCO with Tatas', 'Building railways in Bengal'], ans: 1, exp: 'Seth Hukumchand Marwari set up the first Indian-owned jute mill in Calcutta in 1917. Before this, the Calcutta jute industry was dominated by Scottish merchants.' },
  { q: 'The Indian Factory Act of 1881 prohibited:', opts: ['Women from working in factories', 'Employment of children under 7 and limited working hours for children 7-12 to 9 hours', 'Night shifts', 'Foreign ownership of factories'], ans: 1, exp: 'Factory Act 1881 prohibited employment of children under 7 and limited children (7-12 years) to 9 hours per day. It was India\'s first factory legislation, responding to humanitarian concerns.' },
  { q: 'By 1870, Britain was exporting how many yards of cotton cloth to India annually?', opts: ['1 million yards', '100 million yards', '500 million yards', '995 million yards'], ans: 3, exp: 'In 1800, Britain exported 1 million yards of cotton to India. By 1870, this rose to 995 million yards — flooding India with cheap machine-made cloth, devastating handloom weavers.' },
  { q: 'Indian handloom weavers survived Manchester competition by:', opts: ['Lobbying British government for protection', 'Adopting the fly shuttle for coarser cloth, focusing on special fabrics machines couldn\'t replicate', 'Starting their own mills', 'Moving to agriculture'], ans: 1, exp: 'Indian weavers survived by adopting the fly shuttle (faster output), moving to coarser cloth (where machines competed less), and preserving niche markets for fine Dhaka muslin, Varanasi brocade, and printed textiles.' },
  { q: 'The concept of "seasonal demand for labour" in 19th century urban industries refers to:', opts: ['Demand for agricultural labour', 'Industries like tailoring, bookbinding, and printing having peak demand in certain seasons (London \'season\')', 'Textile mills only operating in summer', 'Workers only available seasonally'], ans: 1, exp: 'In 19th century London, upper-class "season" (Parliament in session, social events) created seasonal peaks for tailors, shoemakers, and printers. Workers endured periods of feast and famine.' },
  { q: 'Why did early industrialists in Britain prefer hand technology over machines for some tasks?', opts: ['Machines were banned by law', 'Certain products needed hand-finishing for quality, and seasonal demand made machines unprofitable', 'Hand technology was faster', 'No machines existed'], ans: 1, exp: 'Some products (superfine cloth, complex designs) needed human skill. Also, seasonal demand (Christmas, fashion seasons) made it uneconomical to invest in machines that would sit idle half the year.' },
  { q: 'TISCO (Tata Iron and Steel Company) was established by:', opts: ['Jamsetji Tata alone (who lived to see its completion)', 'Jamsetji Tata (who planned it) and completed by Dorabji Tata after his death', 'British government', 'SAIL founders'], ans: 1, exp: 'Jamsetji Tata dreamed of an Indian steel plant but died in 1904, before TISCO was established in 1907. His son Dorabji Tata and nephew Ratan Tata saw the vision through to completion.' },
  { q: 'The Swadeshi movement boosted Indian industry because:', opts: ['British allowed Indian factories to import raw materials free', 'Indians boycotted British goods, creating demand for Indian-made cloth and goods', 'Government gave subsidies to Indian mills', 'British companies left India voluntarily'], ans: 1, exp: 'Swadeshi movement (from 1905 Bengal Partition) encouraged Indians to boycott British goods and buy Indian-made products, boosting domestic mills, especially cotton textiles and matches.' },
  { q: 'Women workers in 19th century British factories faced:', opts: ['Equal pay and promotion opportunities', 'Limited to specific industries like textiles with restricted working hours and lower wages', 'No work at all (women didn\'t work)', 'All management positions'], ans: 1, exp: 'Women in 19th century factories were concentrated in textile mills, domestic service, and garment-making with lower wages, restricted hours (Factory Acts), and no promotion to skilled roles.' },
  { q: 'The term "labour aristocracy" in 19th century Britain referred to:', opts: ['Rich industrialists', 'Skilled workers (like engineers, printers) who earned better wages than unskilled labourers', 'Factory supervisors', 'Government-employed workers'], ans: 1, exp: 'Labour aristocracy = skilled workers (machinists, printers, carpenters) who earned significantly higher wages than unskilled factory workers, forming a stable upper tier of the working class.' },
  { q: 'Manchester\'s dominance in cotton textile production was supported by:', opts: ['Its location near cotton fields', 'Its port, coal from nearby Yorkshire, soft water from Pennines, and skilled labour', 'Government protection from foreign competition', 'Slave labour'], ans: 1, exp: 'Manchester had coal from nearby mines, soft water (ideal for cotton processing), humid climate from the Pennines (preventing thread breakage), canals, and later railways connecting it to Liverpool port.' },
  { q: 'The Calcutta jute industry was established mainly by:', opts: ['Indian Marwari entrepreneurs from the start', 'Scottish merchants and entrepreneurs who dominated until late 19th century', 'British government', 'Bengali zamindars'], ans: 1, exp: 'The Calcutta jute industry was initially dominated by Scottish merchants (George Acland, Thomas Duff) who owned most mills. Indian (Marwari) entrepreneurs only entered significantly from the 1890s.' },
  { q: 'The "putting-out system" in proto-industrialisation means:', opts: ['Putting workers out of jobs', 'Merchants put out raw materials to rural households who manufactured goods at home', 'Goods put out for sale', 'Workers put outside factory hours'], ans: 1, exp: 'The putting-out system: merchants "put out" raw materials (wool, cotton) to rural artisan families, who processed them at home, then the merchant collected the finished goods and sold them.' },
  { q: 'By 1911, what proportion of India\'s labour force was employed in factories?', opts: ['Less than 1%', 'About 5%', 'About 15%', 'About 30%'], ans: 0, exp: 'Despite industrial growth, less than 1% of India\'s workforce was in modern factories by 1911. The vast majority worked in agriculture and traditional crafts.' },
  { q: 'The abolition of slavery in the USA (1865) affected world cotton trade because:', opts: ['Cotton production stopped in USA', 'Cotton prices dropped as freed slaves became paid workers producing more cotton', 'India became the only cotton exporter', 'Cotton mills in Britain closed'], ans: 0, exp: 'After US Civil War (1865), cotton production recovered but costs rose as freed slaves demanded wages. India\'s cotton exports to Britain initially fell as US production resumed.' },
  { q: 'Industrial discipline in early factories was enforced through:', opts: ['Democratic worker committees', 'Time-keeping, fines, piece-rate wages, and factory rules imposing regular attendance', 'Government labour inspectors', 'Union agreements'], ans: 1, exp: 'Early factory owners enforced discipline through clocks (time-keeping), fines for lateness, piece-rate wages (tying income to output), and strict factory rules — a sharp shift from agricultural/cottage work rhythms.' },
  { q: 'Why was the cotton textile industry in Ahmedabad called "Manchester of India"?', opts: ['It looked like Manchester architecturally', 'Both cities were major cotton textile producers with similar industrial structures', 'Ahmedabad exported to Manchester', 'British entrepreneurs built both cities'], ans: 1, exp: 'Ahmedabad earned the nickname because, like Manchester, it was a major cotton textile manufacturing city with mills, industrial workers, labour unions, and textile market linkages.' },
  { q: 'India\'s industrial growth before 1947 was restricted because:', opts: ['India lacked raw materials', 'British colonial policies favoured British industry and discouraged Indian industrialisation', 'Indian entrepreneurs had no capital', 'Caste system prevented industrial work'], ans: 1, exp: 'British colonial policies kept India as a raw material supplier and market for British manufactures. High tariffs on British goods were opposed; Indian industrialists faced import competition from British mills.' },
  { q: 'The American Civil War (1861–65) actually temporarily boosted Indian cotton exports because:', opts: ['India started selling to China', 'US cotton supply to Britain was cut off, so Britain bought more cotton from India (Bombay)', 'British mills closed and India supplied itself', 'Suez Canal opened (1869) reducing transport costs'], ans: 1, exp: 'When US Civil War cut off American cotton supply to British mills, demand for Indian cotton (from Bombay hinterland/Deccan) surged, creating a brief cotton boom in Bombay.' },
  { q: 'What was the "Fulling Mill" in medieval England?', opts: ['A mill for grinding grain', 'A mill for cleaning and compressing woollen cloth', 'A mill for spinning wool', 'A mill for dyeing cloth'], ans: 1, exp: 'Fulling mills used water-powered hammers to beat and compress woollen cloth, cleaning it and tightening the fibres. They were among the earliest water-powered machines in medieval England.' },
  { q: 'India\'s early industrialists primarily invested in jute and cotton rather than steel because:', opts: ['Steel was too technical', 'Cotton and jute had ready raw material, market, and lower capital needs; steel needed huge capital and government support', 'Steel was banned by British', 'India had no iron ore'], ans: 1, exp: 'Cotton and jute were accessible to Indian private capital — lower investment, existing raw materials, clear markets. Steel required massive capital, technical expertise, and Tata had to fight colonial opposition to get started.' },
  { q: 'How did the Manchester cotton industry affect the weavers of Surat (Gujarat)?', opts: ['Surat weavers benefited by supplying thread to Manchester', 'Surat\'s weaving industry declined as cheap Manchester cloth flooded markets, ending its 18th-century prosperity', 'Surat became more prosperous making machine cloth', 'No impact — Surat made only silk'], ans: 1, exp: 'Surat was a major 18th-century textile export port. Manchester\'s machine-made cotton cloth that arrived via Bombay in the 19th century destroyed Surat\'s handloom weaving and its role as a textile trade hub.' },
  { q: 'A "Piece-rate" wage system in factories means workers are paid:', opts: ['Per hour worked', 'Per piece of output produced', 'A monthly fixed salary', 'Based on seniority'], ans: 1, exp: 'In a piece-rate system, workers are paid per unit of output (per piece made). This incentivised speed but caused stress, made income unpredictable, and disadvantaged slower workers.' },
  { q: 'Which Indian city became famous for producing "Dacca muslin" (the finest cotton fabric)?', opts: ['Varanasi', 'Dacca (now Dhaka, Bangladesh)', 'Surat', 'Coimbatore'], ans: 1, exp: 'Dacca (Dhaka) in Bengal (now Bangladesh) was famous for producing the finest muslin cloth — so delicate it was called "running water" or "woven air." It declined due to Manchester competition and partition.' },
  { q: 'The Industrial Revolution began in Britain for multiple reasons including:', opts: ['Britain had the largest population in Europe', 'Coal and iron resources, strong maritime trade, colonial raw materials, and early agricultural revolution releasing labour', 'Britain had the most educated scientists', 'British government directly invested in industries'], ans: 1, exp: 'Britain\'s Industrial Revolution was enabled by: abundant coal and iron, colonial trade providing raw materials and markets, agricultural revolution releasing rural labour, strong merchant class, and patent law protecting inventors.' },
  { q: 'Early factories in Britain were often located on rivers because:', opts: ['Rivers provided cheap land', 'Rivers provided water power (before steam), water for processes, and means of transport', 'Workers lived near rivers', 'Raw materials came by river only'], ans: 1, exp: 'Early factories used water wheels (river current) for power, river water for processes, and rivers as transport routes for raw materials and goods. Steam later freed factories from river dependence.' },
  { q: 'The Factory Act of 1891 in India for the first time restricted:', opts: ['Child labour under 14', 'Women\'s working hours and gave them a weekly holiday', 'Night work for all workers', 'Working in certain dangerous industries'], ans: 1, exp: 'Factory Act 1891 restricted women\'s working hours (11 hours max per day), prohibited night work for women, and gave all workers a weekly holiday — an extension of 1881 Act protections.' },
  { q: 'The concept of "value addition" in manufacturing is significant because it shows:', opts: ['How much profit factories make', 'The actual economic contribution of manufacturing beyond raw material value', 'How much tax is paid', 'The size of the factory'], ans: 1, exp: 'Value addition measures the wealth created by the manufacturing process itself — transforming cheaper raw materials into more valuable goods. It is the basis for calculating manufacturing\'s GDP contribution.' },
  { q: 'Robert Owen\'s New Lanark mills are remembered for:', opts: ['Extreme worker exploitation', 'Being a model of industrial welfare — good housing, schools, and no child labour', 'Being Britain\'s first steam-powered mills', 'Producing the finest cotton in Britain'], ans: 1, exp: 'Robert Owen (1771–1858) ran New Lanark mills (Scotland) as a social experiment — providing decent housing, a school, reasonable working hours, and banning child labour, proving welfare and profit could coexist.' },
  { q: 'In proto-industrial (cottage) system, why did merchants prefer rural over urban artisans?', opts: ['Urban artisans were too skilled', 'Rural areas had lower wages, larger surplus labour supply, and fewer guild restrictions', 'Rural areas had better transport', 'Urban areas had no artisans'], ans: 1, exp: 'Rural artisans were cheaper than urban guild-controlled craftsmen, and the countryside had surplus labour from partial agriculture. Rural putting-out systems bypassed restrictive urban craft guild regulations.' },
  { q: 'The "Factory System" replaced the putting-out system because:', opts: ['Peasants refused to do cottage work', 'Factories allowed better supervision, discipline, and use of power machinery impossible in cottages', 'Government banned home production', 'Raw materials were too heavy to distribute'], ans: 1, exp: 'The factory system allowed employers to supervise workers directly, use steam-powered machinery (impossible in homes), enforce discipline and time-keeping, and standardise product quality.' },
  { q: 'Which Indian community predominantly controlled the Bombay cotton mills in the 19th century?', opts: ['Bengali Brahmins and zamindars', 'Parsi and Marwari merchants', 'British and European investors', 'Government (public sector)'], ans: 1, exp: 'Bombay\'s early cotton mills (1854 onwards) were founded and controlled by Parsi entrepreneurs (Dinshaw Petit, Wadia family) and later Marwari merchants, with very limited British investment.' }
];

const SOCIAL_CH13_EXTRA = [
  { q: 'The oldest dated printed book in the world is:', opts: ['Gutenberg Bible (1450)', 'Diamond Sutra (868 CE)', 'Marco Polo\'s Travels (1300)', 'Quran manuscript (700 CE)'], ans: 1, exp: 'The Diamond Sutra (868 CE) is the world\'s oldest dated printed book, printed using woodblock technique in Tang Dynasty China. It was found in a cave at Dunhuang in 1900.' },
  { q: 'Pi Sheng (Bi Sheng) invented moveable type in China in:', opts: ['594 CE', '868 CE', '1040 CE', '1300 CE'], ans: 2, exp: 'Pi Sheng (Bi Sheng) invented the first moveable type — made of baked clay — around 1040 CE during the Song Dynasty, over 400 years before Gutenberg\'s metal type.' },
  { q: 'Johann Gutenberg developed the printing press using:', opts: ['Wooden moveable type', 'Metal moveable type adapted from a screw press used for wine/olive pressing', 'A water-powered printing mechanism', 'Rubber stamps and ink rollers'], ans: 1, exp: 'Gutenberg adapted a screw press (used for pressing wine grapes and olives) with metal moveable type to create his printing press around 1448 in Mainz, Germany.' },
  { q: 'How many copies of the Gutenberg Bible were printed?', opts: ['50 copies', '100 copies', '180 copies', '500 copies'], ans: 2, exp: 'Gutenberg printed about 180 copies of the Bible (1450–55) — some on paper, some on vellum. Each is considered a masterpiece and most surviving copies are in major museum collections.' },
  { q: 'By 1500, approximately how many books had been printed in Europe?', opts: ['1 million', '10 million', '20 million', '100 million'], ans: 2, exp: 'By 1500 (50 years after Gutenberg\'s press), about 20 million books had been printed across Europe in 35,000 different editions. This was the "print revolution."' },
  { q: 'Martin Luther\'s 95 Theses (1517) used print to:', opts: ['Write a personal diary', 'Spread his challenge to Catholic Church doctrine rapidly across Europe', 'Publish a Bible in German', 'Denounce the printing press'], ans: 1, exp: 'Luther\'s 95 Theses, nailed to a Wittenberg church door, were quickly printed and distributed across Germany and Europe within weeks — print made the Protestant Reformation possible.' },
  { q: 'The Catholic Church\'s Index of Prohibited Books (Index Librorum Prohibitorum) was established in:', opts: ['1450', '1517', '1558', '1600'], ans: 2, exp: 'The Catholic Church published the first Index Librorum Prohibitorum in 1558 to list books forbidden to Catholics — an attempt to control what the faithful read in the age of print.' },
  { q: 'Menocchio (Domenico Scandella) was an Italian miller who:', opts: ['Invented a new printing machine', 'Read printed books and formed heretical views, leading to his execution by the Inquisition (1599)', 'Published banned books secretly', 'Helped spread Luther\'s ideas in Italy'], ans: 1, exp: 'Menocchio was a 16th-century miller who read various printed books and combined ideas creatively, forming views on God and creation the Inquisition considered heretical. He was burned at the stake in 1599.' },
  { q: 'Chapbooks in Europe were:', opts: ['Scholarly texts for universities', 'Cheap, small popular books sold by peddlers containing ballads, folklore, and almanacs', 'Government-approved newspapers', 'Scientific publications'], ans: 1, exp: 'Chapbooks were cheap, small booklets (often 8-24 pages, folded once) sold by peddlers (chapmen) containing popular ballads, fairy tales, almanacs, and religious texts — affordable entertainment for common people.' },
  { q: 'Coffee houses in 17th-18th century England served as spaces where:', opts: ['Only wealthy men drank coffee', 'People read, discussed, and shared ideas from newspapers and pamphlets — literate and illiterate together', 'Seditious literature was secretly sold', 'Coffee was first introduced to England'], ans: 1, exp: 'Coffee houses were social centres where newspapers and pamphlets were read aloud — allowing even illiterate people to access news and ideas. They were called "penny universities" (cost of entry = 1 penny).' },
  { q: 'Samuel Richardson is associated with the history of print because he:', opts: ['Established the first lending library', 'Wrote Pamela (1740), considered the first modern English novel, and ran a printing shop + lending library', 'Printed the Gutenberg Bible', 'Founded the first Indian newspaper'], ans: 1, exp: 'Samuel Richardson was a printer who wrote Pamela (1740), considered by many the first English novel. He also ran a printing shop and circulating library, connecting print production with fiction reading.' },
  { q: 'Lending libraries (circulating libraries) became widespread from the:', opts: ['1600s', '1740s', '1800s', '1850s'], ans: 1, exp: 'Lending libraries became widespread from the 1740s in Britain. For a small subscription fee, readers could borrow books, making reading accessible to people who couldn\'t afford to buy books.' },
  { q: 'The first printing press established in India (in Goa) was set up by:', opts: ['British East India Company (1600)', 'Portuguese Jesuit missionaries (1556)', 'Dutch traders (1580)', 'Mughal emperor Akbar (1565)'], ans: 1, exp: 'Portuguese Jesuit missionaries established the first printing press in India at Goa in 1556, printing books in Konkani and Tamil to aid Christian missionary work.' },
  { q: 'James Augustus Hickey\'s Bengal Gazette (1780) was shut down because:', opts: ['It ran out of funding', 'It printed criticism of Governor-General Hastings, who seized the press in 1782', 'It was in a foreign language', 'The publisher died'], ans: 1, exp: 'Hickey\'s Bengal Gazette (1780) was India\'s first printed newspaper. Hickey attacked Governor-General Warren Hastings; Hastings sued for libel and finally seized the press in 1782.' },
  { q: 'Sambad Kaumudi (1821) was founded by:', opts: ['Bal Gangadhar Tilak', 'Ram Mohan Roy', 'Dayananda Saraswati', 'Lala Lajpat Rai'], ans: 1, exp: 'Ram Mohan Roy founded Sambad Kaumudi (1821) in Bengali, and Mirat-ul-Akhbar in Persian — reformist newspapers advocating against sati, for widow remarriage, and for rational thinking.' },
  { q: 'The Vernacular Press Act of 1878 was called the "Gagging Act" because:', opts: ['It taxed Indian-language newspapers', 'It allowed the government to seize press and materials printing "seditious" content against British rule', 'It banned all languages except English', 'It required government approval before printing'], ans: 1, exp: 'Vernacular Press Act 1878 (Lord Lytton) gave magistrates power to seize press and materials of vernacular newspapers printing anything the government deemed "seditious" — while English press remained exempt.' },
  { q: 'Bal Gangadhar Tilak was associated with which newspapers?', opts: ['Bengal Gazette and Sambad Kaumudi', 'Kesari (Marathi) and Mahratta (English)', 'Al-Hilal and Yugantar', 'The Hindu and Tribune'], ans: 1, exp: 'Tilak published Kesari (Marathi-language, 1881) and Mahratta (English-language, 1881), using them to spread radical nationalism, critique colonial policies, and awaken national consciousness.' },
  { q: 'Benedict Anderson\'s "Imagined Communities" (1983) argues that nationalism was created through:', opts: ['Military conquest', 'Print capitalism creating shared language and consciousness across distances', 'Economic development', 'Religious movements'], ans: 1, exp: 'Benedict Anderson argued that print capitalism — books and newspapers in vernacular languages — allowed people who never met to imagine themselves as one "nation," creating national consciousness.' },
  { q: 'The Bombay Samachar (1822) is significant because:', opts: ['It was India\'s first English newspaper', 'It was Asia\'s oldest continuously published newspaper (Gujarati language, Parsi owned)', 'It published the first Indian political party\'s manifesto', 'It was banned by the British immediately'], ans: 1, exp: 'Bombay Samachar (1822), a Gujarati-language newspaper owned by the Parsi community, is Asia\'s oldest continuously published newspaper — still publishing today.' },
  { q: 'The Erasmus of Rotterdam cautioned against print culture because:', opts: ['He feared job losses for scribes', 'He worried that cheap popular books would flood minds with "sludge" and that trivial content would drown serious scholarship', 'He was employed by the Catholic Church to ban books', 'He couldn\'t read'], ans: 1, exp: 'Erasmus (1469–1536), the humanist scholar, worried that the print press would create an avalanche of trivial, poorly thought-out books drowning serious intellectual exchange in "sludge."' },
  { q: 'Which of the following was NOT among the early effects of the printing press in Europe?', opts: ['Spread of Protestant Reformation', 'Standardisation of languages', 'Immediate end of the Catholic Church\'s power', 'Creation of new reading publics'], ans: 2, exp: 'The printing press spread Reformation ideas, helped standardise national languages, and created mass readership — but the Catholic Church\'s institutional power wasn\'t immediately destroyed; it adapted and survived.' },
  { q: 'Woodblock printing was first developed in China in approximately:', opts: ['200 CE', '400 CE', '594 CE', '868 CE'], ans: 2, exp: 'Woodblock printing was first developed in China around 594 CE during the Sui Dynasty, initially used for Buddhist texts. The Diamond Sutra (868 CE) is the oldest DATED example.' },
  { q: 'Marco Polo\'s return to Europe from China (1295) brought knowledge of:', opts: ['Chinese silk production', 'Chinese woodblock printing technology', 'Chinese gunpowder and weapons', 'Chinese tea cultivation'], ans: 1, exp: 'Marco Polo (1295) brought knowledge of Chinese woodblock printing to Europe, where it was initially used for printing playing cards and religious images before Gutenberg developed the moveable type press.' },
  { q: 'The printing press was called a "divine art" or "holy craft" because:', opts: ['Monks only operated printing presses', 'It helped spread religious texts and was seen as God\'s gift for spreading His word', 'The Pope declared it sacred', 'It was developed in a monastery'], ans: 1, exp: 'Philip Melanchthon called printing "the ultimate gift of God." Early printers saw themselves as serving God by spreading the Bible and religious knowledge — printing was deeply tied to religious purpose initially.' },
  { q: 'Al-Hilal (1912) was a newspaper associated with:', opts: ['Bal Gangadhar Tilak', 'Maulana Abul Kalam Azad', 'Lala Lajpat Rai', 'Bipin Chandra Pal'], ans: 1, exp: 'Al-Hilal (1912) was an Urdu weekly newspaper published by Maulana Abul Kalam Azad, advocating Pan-Islamic ideas and Indian nationalism. It was banned in 1914 under the Press Act.' },
  { q: 'Yellow journalism in late 19th century USA is best described as:', opts: ['High-quality investigative journalism', 'Sensationalist, exaggerated reporting using eye-catching headlines to increase circulation', 'Journalism supporting labour rights', 'Scientific journalism using only facts'], ans: 1, exp: 'Yellow journalism (Pulitzer vs Hearst rivalry in 1890s New York) used sensationalist stories, exaggerated headlines, and illustrations to boost sales. It influenced US public opinion toward the Spanish-American War (1898).' },
  { q: 'Why did women reading novels cause "moral panic" in the 18th century?', opts: ['Novels contained violent content', 'Moralists feared novels gave women romantic ideas and made them dissatisfied with domestic life', 'Novels were too expensive for women', 'Women reading in public was illegal'], ans: 1, exp: 'Moralists feared that romantic novels encouraged women to dream of impossible love, gave them "ideas above their station," made them negligent of domestic duties, and undermined submissiveness.' },
  { q: 'Print helped create "public opinion" because:', opts: ['Governments used print to control opinions', 'It allowed ideas to circulate widely, reach many people, and stimulate debate beyond small elite circles', 'Only educated people read', 'Print was only used for government announcements'], ans: 1, exp: 'Print allowed ideas, criticism, satire, and debate to circulate among thousands simultaneously, creating a "public sphere" where common people could engage with political ideas — basis for modern public opinion.' },
  { q: 'The Index of Prohibited Books (Catholic Church, 1558) was maintained until:', opts: ['1700', '1800', '1900', '1966'], ans: 3, exp: 'The Index Librorum Prohibitorum was maintained by the Catholic Church until 1966, when it was officially abolished by Pope Paul VI, though its moral force was already weakened.' },
  { q: 'Printing in India before 1780 (before Bengal Gazette) was primarily used for:', opts: ['Political newspapers', 'Religious texts (Christian missionary, then Sanskrit and vernacular religious works)', 'Government official communications', 'Trade catalogues'], ans: 1, exp: 'Before secular newspapers, printing in India (from Goa 1556) was used for Christian missionary texts, then Sanskrit and vernacular religious and literary works. The first secular newspaper came in 1780.' },
  { q: 'The term "broadsheet" in print history refers to:', opts: ['A large-format quality newspaper', 'Single-sheet publications printed on one side covering current events, ballads, or announcements', 'A technical manual', 'A government gazette'], ans: 1, exp: 'Broadsheets were single-sheet publications (printed on one or both sides) covering news events, executions, stories of prodigies, or popular ballads — cheap and widely circulated among all classes.' },
  { q: 'How did print culture contribute to the standardisation of European languages?', opts: ['Governments issued official word lists', 'Printing in one regional dialect created a standard written form that spread through mass production of books', 'Language academies were established with printing support', 'Church Latin was replaced by print Latin'], ans: 1, exp: 'When printers chose one regional dialect to print in (e.g., Luther\'s German Bible in Saxon dialect), that dialect gained wide circulation and eventually became the standard written language of the nation.' },
  { q: 'Pulp fiction and penny dreadfuls in 19th century Britain were:', opts: ['High-quality literary fiction', 'Cheap, sensationalist serialised fiction for working-class readers in the age of mass literacy', 'Rare collectors\' items', 'Scientific publications for children'], ans: 1, exp: 'Penny dreadfuls and pulp fiction were cheap serialised stories (crime, horror, adventure) sold for a penny, targeting the newly literate working class — mass-market entertainment created by print technology.' },
  { q: 'The Vernacular Press Act 1878 exempted English-language newspapers because:', opts: ['English newspapers were less widely read', 'Colonial government wanted to appear liberal to British public while controlling Indian opinion', 'English editors were British citizens', 'English papers never criticised the government'], ans: 1, exp: 'The exemption of English press from the Vernacular Press Act showed colonial double standards — vernacular (Indian-language) papers reaching mass Indian audiences were controlled, while English papers read by educated elites were exempt.' },
  { q: 'Ram Mohan Roy used newspapers like Sambad Kaumudi to campaign for:', opts: ['Independence from British rule', 'Social reforms including abolition of sati and promotion of widow remarriage', 'Economic boycott of British goods', 'Revival of Sanskrit education'], ans: 1, exp: 'Ram Mohan Roy used newspapers to advocate social reforms: abolishing sati (succeeded in 1829 Bengal Sati Regulation), widow remarriage, and rational/scientific education — making him the "Father of Indian Renaissance."' },
  { q: 'Which European humanist was known for circulating ideas through print correspondence across the continent?', opts: ['Martin Luther', 'Erasmus of Rotterdam', 'Philip Melanchthon', 'John Calvin'], ans: 1, exp: 'Erasmus of Rotterdam used the printing press to circulate his writings and correspondence across Europe, creating a "republic of letters" — a network of humanist scholars connected through print.' },
  { q: 'The Protestant Reformation would not have spread as rapidly without print because:', opts: ['Luther used print to reach only German-speaking areas', 'Print allowed Luther\'s ideas to spread in multiple languages across Europe within weeks rather than years', 'The Catholic Church banned print', 'Print was only available in Germany'], ans: 1, exp: 'Without print, Luther\'s 95 Theses would have remained a local university debate. Print translated and spread them across Europe within weeks, enabling the Reformation\'s rapid spread before the Church could suppress it.' },
  { q: 'The first newspaper in India was the Bengal Gazette (1780). Its full name was:', opts: ['Bengal Gazette', 'Bengal Gazette or Calcutta General Advertiser', 'Hickey\'s Bombay Courier', 'India Gazette'], ans: 1, exp: 'The full name was "Bengal Gazette or Calcutta General Advertiser." Established by James Augustus Hickey, it was a weekly paper covering news, gossip, and commentary critical of the colonial administration.' },
  { q: 'The Kesari newspaper established by Tilak was written in:', opts: ['English', 'Hindi', 'Marathi', 'Urdu'], ans: 2, exp: 'Kesari (meaning "Lion") was a Marathi-language weekly (later daily) founded by Bal Gangadhar Tilak in 1881. It reached Marathi-speaking masses and was one of the most influential nationalist newspapers.' },
  { q: 'The role of print in the Indian independence movement was primarily to:', opts: ['Spread British policies to Indians', 'Create national consciousness, mobilise public opinion, and connect dispersed nationalist leaders', 'Provide entertainment for educated classes', 'Teach English to Indians'], ans: 1, exp: 'Nationalist print (Tilak\'s Kesari, Annie Besant\'s New India, The Hindu, Amrita Bazar Patrika) mobilised public opinion, spread nationalist ideas, connected leaders and masses, and created a sense of national identity.' },
  { q: 'Reader\'s Digest (founded 1922) is significant in print history because it:', opts: ['Was the first illustrated magazine', 'Made condensed versions of articles from other magazines accessible to a mass readership', 'Was the first digital publication', 'Published only scientific research'], ans: 1, exp: 'Reader\'s Digest (1922, USA) condensed and simplified articles from other publications into a single magazine, reaching millions of readers who preferred shorter content — a key development in mass-market print.' },
  { q: 'Why was print described as creating a "reading revolution" in 18th-century Europe?', opts: ['Everyone suddenly could read', 'People shifted from reading a few texts repeatedly to reading many texts once — creating a culture of information consumption', 'Printing replaced all oral tradition', 'Books became free of cost'], ans: 1, exp: 'The "reading revolution" was the shift from "intensive reading" (re-reading a few religious texts deeply, often aloud) to "extensive reading" (reading many texts once, silently, for information and entertainment).' },
  { q: 'Comic books and cartoons in 20th-century print culture were significant because:', opts: ['They were only for children', 'They made print accessible to non-readers through images, creating new audiences for print media', 'They had no political content', 'They were too expensive'], ans: 1, exp: 'Comics and cartoons (from newspaper strips to comic books) used images with minimal text, making print media accessible to semi-literate readers, children, and those new to reading — expanding print culture.' }
];
